typedef const char * ALPHA_t;

typedef const char * SP_t;

typedef const char * HTAB_t;

typedef const char * LF_t;

typedef const char * CR_t;

typedef const char * DQUOTE_t;

/* a bareword may hold what a file name, an IPv4 address or a host name holds */
typedef const char * wordchars_t;

typedef const char * word_start_t;

typedef const char * word_non_digit_t;

/* `int` is declared before `word`, so that a bare number is an `int` (the scanner keeps the
longest match, first declared on a tie) */
typedef const char * int_t;

typedef const char * word_t;

/* a quoted string, with backslash escapes */
typedef const char * str_t;

typedef const char * str_char_t;

/* `#` to the end of the line; a backslash at the end of a line continues it */
typedef const char * comment_t;

typedef const char * comment_char_t;

typedef const char * continuation_t;

/* what is skipped between the elements of a phrase: blanks, newlines, comments, continuations */
typedef const char * ws_t;

typedef const char * string_t;

typedef enum {
    YESNO_YES,   /* yes */
    YESNO_NO   /* no */
} yesno_t;

typedef const char * wildcard_t;

typedef const char * address_t;

typedef enum {
    ENTRY_LISTEN,   /* listen */
    ENTRY_PORT,   /* port */
    ENTRY_TLS,   /* tls */
    ENTRY_INSECURE,   /* insecure */
    ENTRY_OFFICIAL_KLINES,   /* official-klines */
    ENTRY_CERTIFICATE,   /* certificate */
    ENTRY_KEY,   /* key */
    ENTRY_AUTHORIZED,   /* authorized */
    ENTRY_AUTHORIZE,   /* authorize */
    ENTRY_CANDLES,   /* candles */
    ENTRY_BACKFILL,   /* backfill */
    ENTRY_DATABASE,   /* database */
    ENTRY_LIVE_BINS,   /* live-bins */
    ENTRY_HEAT_DB   /* heat-db */
} entry_kind_t;
struct entry_s {
    entry_kind_t kind;
    address_t address;
    long long hyper_int;
    yesno_t yesno;
    string_t string;
    size_t _line;   /* for bind_error */
};

struct config_s {
    struct config_s *_link;
    entry_t entry;
};

/* ---- AST traversal (visit) and transform (map) ---- */
typedef enum {
    NODE_CONFIG,
    NODE_ENTRY
} node_kind_t;

typedef void (*visit_fn)(const void *node, node_kind_t kind, void *ctx);
typedef void (*map_fn)(void *node, node_kind_t kind, void *ctx);

static void __attribute__((unused)) visit_config(const struct config_list *, visit_fn f, void *ctx);
static void __attribute__((unused)) map_config(struct config_list *, map_fn f, void *ctx);
static void __attribute__((unused)) visit_entry(const entry_t *, visit_fn f, void *ctx);
static void __attribute__((unused)) map_entry(entry_t *, map_fn f, void *ctx);

static void visit_config(const struct config_list *head, visit_fn f, void *ctx) {
    const config_t *n;
    for (n = (head)->head; n; n = n->_link) {
        f(n, NODE_CONFIG, ctx);
        visit_entry(&n->entry, f, ctx);
    }
}

static void map_config(struct config_list *head, map_fn f, void *ctx) {
    config_t *n;
    for (n = (head)->head; n; n = n->_link) {
        map_entry(&n->entry, f, ctx);
        f(n, NODE_CONFIG, ctx);
    }
}

static void visit_entry(const entry_t *n, visit_fn f, void *ctx) {
    if (!n) return;
    f(n, NODE_ENTRY, ctx);
}

static void map_entry(entry_t *n, map_fn f, void *ctx) {
    if (!n) return;
    f(n, NODE_ENTRY, ctx);
}


/* ---- free (drop a parsed tree) ---- */
static void free_config_fields(config_t *n);
static void free_config_nodes(struct config_list *head);
static void free_config(struct config_list *head);
static void free_entry_fields(entry_t *n);
static void free_entry(entry_t *n);

static void free_config_fields(config_t *n) {
    if (!n) return;
    free_entry(&n->entry);
}

static void free_config_nodes(struct config_list *head) {
    config_t *n = (head)->head, *next;
    while (n) {
        next = (n)->_link;
        free_config_fields(n);
        n = next;
    }
    (head)->head = NULL; (head)->tail = &(head)->head;
}
static void free_config(struct config_list *head) {
    free_config_nodes(head);
    free_arena();
}

static void free_entry_fields(entry_t *n) {
    if (!n) return;
}

static void free_entry(entry_t *n) {
    if (!n) return;
    free_entry_fields(n);
}


/* ---- bind (run action jets bottom-up, children first) ---- */
/* An action reports a semantic error with bind_error("fmt", ...),
   as a parse.y action calls yyerror: the walk carries on, and the
   parse fails once it ends.  The message is tagged with the line the
   action's node starts on.  bind_report, when set, sees every error
   (a config grammar's epilogue points it at conf_error); otherwise the first
   becomes the parse error. */
#include <stdarg.h>
#include <stdio.h>
static size_t bind_errors, bind_line, bind_err_line;
static char bind_err_msg[512];
static void (*bind_report)(size_t line, const char *msg);
static void bind_error(const char *fmt, ...)
    __attribute__((format(printf, 1, 2), unused));
static void bind_error(const char *fmt, ...) {
    char msg[512];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(msg, sizeof msg, fmt, ap);
    va_end(ap);
    if (bind_errors++ == 0) {
        bind_err_line = bind_line;
        snprintf(bind_err_msg, sizeof bind_err_msg, "%s", msg);
    }
    if (bind_report) bind_report(bind_line, msg);
}

static void bind_config(struct config_list *head);
static void bind_entry(entry_t *n);

static void bind_config(struct config_list *head) {
    config_t *n;
    for (n = (head)->head; n; n = n->_link) {
        bind_entry(&n->entry);
    }
}

static void bind_entry(entry_t *n) {
    if (!n || !n->_line) return;  /* not in the config */
    bind_line = n->_line;
    
    switch (n->kind) {
    case ENTRY_LISTEN:
        if (n->address == NULL || n->address[0] == '\0') { bind_error("listen needs an address"); return; }
        set_str(&conf->listen_addr, n->address);
        break;
    case ENTRY_PORT:
        if (n->hyper_int < 1 || n->hyper_int > 65535) { bind_error("the port must be between 1 and 65535"); return; }
        conf->port = (int)n->hyper_int;
        break;
    case ENTRY_TLS:      conf->tls = n->yesno == YESNO_YES; break;
    case ENTRY_INSECURE: conf->insecure = n->yesno == YESNO_YES; break;
    case ENTRY_OFFICIAL_KLINES: conf->official_klines = n->yesno == YESNO_YES; break;
    case ENTRY_CERTIFICATE: set_str(&conf->certificate, n->string); break;
    case ENTRY_KEY:         set_str(&conf->key, n->string); break;
    case ENTRY_AUTHORIZED:  set_str(&conf->authorized, n->string); break;
    case ENTRY_AUTHORIZE: {
        char **p;
        if (strncmp(n->string, "SHA256:", 7) != 0 || strlen(n->string) != 7 + 64 ||
            strspn(n->string + 7, "0123456789abcdefABCDEF") != 64) {
            bind_error("authorize wants SHA256: and 64 hexadecimal digits");
            return;
        }
        p = realloc(conf->authorize, (conf->nauthorize + 1) * sizeof *p);
        if (p == NULL) { perror("candled"); exit(1); }
        conf->authorize = p;
        conf->authorize[conf->nauthorize] = strdup(n->string);
        if (conf->authorize[conf->nauthorize] == NULL) { perror("candled"); exit(1); }
        conf->nauthorize++;
        break;
    }
    case ENTRY_CANDLES:   set_str(&conf->candles, n->string); break;
    case ENTRY_BACKFILL:  set_str(&conf->backfill, n->string); break;
    case ENTRY_DATABASE:  set_str(&conf->database, n->string); break;
    case ENTRY_LIVE_BINS: set_str(&conf->live_bins, n->string); break;
    case ENTRY_HEAT_DB:   set_str(&conf->heat_db, n->string); break;
    default: break;
    }

}


