static bool parse_body_config(parser_t *p, struct config_list *out);
static bool (parse_rule_config)(parser_t *p, struct config_list *out) {
    bool ok_;
    if (p->depth >= HBNF_MAX_DEPTH) { fail (p, "shallower nesting", 0, p->text + p->pos, p->pos < p->len ? 1 : 0); return false; }
    if (!p->quiet && p->depth < 24) { p->stk[p->depth] =  1; p->stkpos[p->depth] = p->pos; }
    p->depth++;
    ok_ = parse_body_config(p, out);
    p->depth--;
    return ok_;
}
static inline bool parse_body_config(parser_t *p, struct config_list *out) {
    struct config_list head;
    (&head)->head = NULL; (&head)->tail = &(&head)->head;
    size_t count = 0;
    hbnf_chunk *ac_ = NULL; size_t au_ = 0; int open_ = 0;
    while (p->pos < p->len && count < 1) {
        ac_ = hbnf_arena; au_ = ac_ ? ac_->used : 0; open_ = 1;
        config_t *nn = (config_t *)hbnf_alloc(sizeof(*nn));
        if (!nn) hbnf_oom();
        size_t save = p->pos;
        skip_ws(p);
        if (!parse_rule_entry(p, &nn->entry)) { goto alt_fail_1; }
        goto have;
alt_fail_1:
        p->pos = save; break;
have:
        *(&head)->tail = nn; (&head)->tail = &(nn)->_link;
        open_ = 0;
        count++;
    }
    if (open_ && ac_ && hbnf_arena == ac_) { memset (ac_->data + au_, 0, ac_->used - au_); ac_->used = au_; }
    *out = head; if (!(out)->head) (out)->tail = &(out)->head; return true;
}
