static bool parse_body_string(parser_t *p, string_t *out);
static bool (parse_rule_string)(parser_t *p, string_t *out) {
    bool ok_;
    if (p->depth >= HBNF_MAX_DEPTH) { fail (p, "shallower nesting", 0, p->text + p->pos, p->pos < p->len ? 1 : 0); return false; }
    if (!p->quiet && p->depth < 24) { p->stk[p->depth] =  21; p->stkpos[p->depth] = p->pos; }
    p->depth++;
    ok_ = parse_body_string(p, out);
    p->depth--;
    return ok_;
}
static inline bool parse_body_string(parser_t *p, string_t *out) {
    { size_t n = scan_str(p->text, p->pos, p->len); if (n) { *out = hbnf_str_value(p->text + p->pos, n); p->pos += n; return true; } }
    { size_t n = scan_word(p->text, p->pos, p->len); if (n && kw_lookup(p->text + p->pos, n) == KWID_NONE) { *out = hbnf_str_append(p->text + p->pos, n); p->pos += n; return true; } }
    fail(p, "a string", 0, p->text + p->pos, 0);
    return false;
}
