static inline bool parse_body_yesno(parser_t *p, yesno_t *out) {
    if (p->pos >= p->len) { fail(p, "a yesno", 0, "end of input", 0); return false; }
    if (HBNF_WORD_AT(p, scan_word) == 3 && memcmp(p->text + p->pos, "yes", 3) == 0) {
        p->pos += 3; *out = YESNO_YES; return true; }
    else if (HBNF_WORD_AT(p, scan_word) == 2 && memcmp(p->text + p->pos, "no", 2) == 0) {
        p->pos += 2; *out = YESNO_NO; return true; }
    else { fail(p, "`yes` or `no`", 0, p->text + p->pos, 0); return false; }
}
