__attribute__((unused))
static void hbnf_path_str(const parser_t *p, char *buf, size_t n) {
    size_t o = 0;  unsigned i;
    buf[0] = 0;
    for (i = 0; i < p->err_depth; i++) {
        const char *s = hbnf_rn[p->err_stk[i]];
        size_t l;
        if (!s) continue;
        l = strlen(s);
        if (o + l + 4 >= n) break;
        if (o) { memcpy(buf + o, " > ", 3);  o += 3; }
        memcpy(buf + o, s, l);  o += l;  buf[o] = 0;
    }
}

/* An error in something that takes more than a line: where the innermost
   enclosing rule that began on an earlier line began, with its line. */
static void hbnf_open_note(parser_t *p, char *err, size_t errlen, int at_end) {
    unsigned i;  size_t el = strlen(err);
    for (i = p->err_depth; i-- > 0; ) {
        const char *s = hbnf_rn[p->err_stk[i]];
        size_t sp = p->err_stkpos[i], l, c, ls, le;
        if (!s) continue;
        while (sp < p->len && (p->text[sp] == ' ' || p->text[sp] == '\t' || p->text[sp] == '\n' || p->text[sp] == '\r')) sp++;
        line_col(p, sp, &l, &c);
        if (l + (at_end ? 1 : 3) > p->err_line) continue;
        for (ls = sp; ls > 0 && p->text[ls - 1] != '\n'; ls--) ;
        for (le = sp; le < p->len && p->text[le] != '\n'; le++) ;
        snprintf(err + el, errlen - el,
                 at_end ? "\n  %zu:%zu:%zu: the %s that begins here is not finished:\n  %.*s\n  %*s^"
                        : "\n  %zu:%zu:%zu: inside the %s that begins here:\n  %.*s\n  %*s^",
                 l, c, sp, s, (int)(le - ls), p->text + ls, (int)(sp - ls), "");
        return;
    }
}

bool hbnf_parse(const char *text, struct config_list *out, char *err, size_t errlen, size_t *err_line, size_t *err_col);
bool hbnf_parse(const char *text, struct config_list *out,
                  char *err, size_t errlen, size_t *err_line, size_t *err_col) {
    parser_t p = { text, strlen(text), 0, (size_t)-1, 0, 0, NULL, NULL, 0, 0 };
    memset(out, 0, sizeof *out);   /* the rules fill it directly and expect it clear */
    p.quiet = 1;   /* the first pass records no failures; one that fails is read again */
    p.stack_lim = (const char *)__builtin_frame_address(0) - (size_t)HBNF_MAX_DEPTH * 256;
start_:
    if (!parse_rule_config(&p, out)) goto fail_;
    skip_ws(&p);
    if (p.pos != p.len) { fail(&p, p.pos == 0 ? "a statement" : "end of statement", 0, p.text + p.pos, 1); goto fail_; }
    bind_errors = 0; bind_line = 0; bind_err_line = 0; bind_err_msg[0] = '\0';
    bind_config(out);
    if (bind_errors) {
        snprintf(err, errlen, "%s", bind_err_msg);
        *err_line = bind_err_line; *err_col = 0;
        return false;
    }
    return true;
fail_:
    if (p.quiet) {
        memset(out, 0, sizeof *out);   /* the first pass left a tree here, and the fields of alternatives share space */
        p = (parser_t){ text, strlen(text), 0, (size_t)-1, 0, 0, NULL, NULL, 0, 0 };
        goto start_;
    }
    goto err;
err:
    if (p.err_pos != (size_t)-1) line_col(&p, p.err_pos, &p.err_line, &p.err_col);
    { const char *f = p.err_found ? p.err_found : "end of input";
      int at_end = p.err_pos >= p.len;
      if (at_end) f = "end of statement";
      size_t fl = at_end ? strlen(f) : p.err_found_len;
      char want[640];
      want_text(&p, want, sizeof want);
      if (p.text && p.err_line >= hbnf_line_base) {
          const char *l; size_t ll;
          { const char *s = p.text; size_t ln = p.err_line - hbnf_line_base + 1;
            while (ln > 1) {
                const char *nl = strchr(s, '\n');
                if (!nl) break;
                s = nl + 1; ln--;
            }
            const char *nl = strchr(s, '\n');
            l = s; ll = nl ? (size_t)(nl - s) : strlen(s); }
          char pad[64];
          size_t w = p.err_col > 1 ? p.err_col - 1 : 0;
          if (w > sizeof pad - 1) w = sizeof pad - 1;
          memset(pad, ' ', w); pad[w] = '\0';
          snprintf(err, errlen, "%zu:%zu:%zu: expected %s, found %.*s\n  %.*s\n  %s^", p.err_line, p.err_col, p.err_pos, want, (int)fl, f, (int)ll, l, pad);
          hbnf_open_note(&p, err, errlen, at_end);
      } else {
          snprintf(err, errlen, "expected %s, found %.*s", want, (int)fl, f);
      }
    }
    *err_line = p.err_line; *err_col = p.err_col;
    return false;
}
static size_t hbnf_decode_utf8(const char *s, size_t pos, size_t len, uint32_t *cp) {
    if (pos >= len) return 0;
    unsigned char b0 = (unsigned char)s[pos];
    uint32_t c; size_t n;
    if (b0 < 0x80) { *cp = b0; return 1; }
    else if ((b0 & 0xE0) == 0xC0) { n = 2; c = b0 & 0x1F; }
    else if ((b0 & 0xF0) == 0xE0) { n = 3; c = b0 & 0x0F; }
    else if ((b0 & 0xF8) == 0xF0) { n = 4; c = b0 & 0x07; }
    else return 0;
    if (pos + n > len) return 0;
    for (size_t k = 1; k < n; k++) {
        unsigned char b = (unsigned char)s[pos + k];
        if ((b & 0xC0) != 0x80) return 0;
        c = (c << 6) | (b & 0x3F);
    }
    if ((n == 2 && c < 0x80) || (n == 3 && c < 0x800) || (n == 4 && c < 0x10000) || c > 0x10FFFF || (c >= 0xD800 && c <= 0xDFFF)) return 0;
    *cp = c; return n;
}

